'use client';

import React, { useState, useEffect } from 'react';
import { Volume2, VolumeX, Radio, Clock, ShieldCheck, Zap, Sparkles, Navigation } from 'lucide-react';
import { railAudio } from '../utils/audio';

interface NavbarProps {
  onTrainHorn?: () => void;
}

export const Navbar: React.FC<NavbarProps> = () => {
  const [timeStr, setTimeStr] = useState<string>('');
  const [soundActive, setSoundActive] = useState<boolean>(true);
  const [hornPlaying, setHornPlaying] = useState<boolean>(false);

  useEffect(() => {
    const updateTime = () => {
      const now = new Date();
      setTimeStr(
        now.toLocaleTimeString('en-IN', {
          timeZone: 'Asia/Kolkata',
          hour12: true,
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        })
      );
    };
    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  const toggleSound = () => {
    const next = !soundActive;
    setSoundActive(next);
    railAudio.setSoundEnabled(next);
    if (next) {
      railAudio.playIRChime();
    }
  };

  const triggerHorn = () => {
    setHornPlaying(true);
    railAudio.playTrainHorn();
    setTimeout(() => setHornPlaying(false), 1200);
  };

  return (
    <header className="sticky top-0 z-50 backdrop-blur-xl bg-slate-950/75 border-b border-cyan-500/20 shadow-[0_4px_30px_rgba(0,0,0,0.5)]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        {/* Logo & Brand */}
        <div className="flex items-center gap-3.5 group cursor-pointer">
          <div className="relative flex items-center justify-center w-12 h-12 rounded-2xl bg-gradient-to-tr from-cyan-600 via-blue-600 to-indigo-600 shadow-[0_0_20px_rgba(6,182,212,0.6)] group-hover:scale-105 transition-all duration-300">
            <Navigation className="w-6 h-6 text-white transform -rotate-45 animate-pulse" />
            <span className="absolute -top-1 -right-1 flex h-3.5 w-3.5">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-cyan-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-3.5 w-3.5 bg-cyan-500"></span>
            </span>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl sm:text-2xl font-black tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-sky-300 to-white font-mono">
                RAILPULSE<span className="text-cyan-400">.AI</span>
              </h1>
              <span className="hidden sm:inline-block px-2 py-0.5 text-[10px] uppercase font-bold tracking-widest bg-cyan-500/10 text-cyan-300 border border-cyan-500/30 rounded-full shadow-[0_0_10px_rgba(6,182,212,0.2)]">
                LIVE ETA v3.4
              </span>
            </div>
            <p className="text-[11px] text-slate-400 flex items-center gap-1.5 font-medium">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span>
              Where is My Train • Real-Time Satellite Tracking
            </p>
          </div>
        </div>

        {/* Live GPS & Clock & Audio Controls */}
        <div className="flex items-center gap-3 sm:gap-5">
          {/* Live IST Clock */}
          <div className="hidden md:flex items-center gap-2 px-3.5 py-1.5 rounded-xl bg-slate-900/90 border border-slate-700/50 text-slate-200 text-xs font-mono shadow-inner">
            <Clock className="w-3.5 h-3.5 text-cyan-400" />
            <span className="text-slate-400">IST:</span>
            <span className="text-cyan-300 font-semibold">{timeStr || '12:00:00 PM'}</span>
          </div>

          {/* GPS Live Telemetry Pill */}
          <div className="hidden lg:flex items-center gap-2 px-3 py-1.5 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-300 text-xs font-medium">
            <Radio className="w-3.5 h-3.5 text-emerald-400 animate-spin" style={{ animationDuration: '4s' }} />
            <span>GPS Locked • ISRO NavIC</span>
          </div>

          {/* Train Horn SFX Button */}
          <button
            onClick={triggerHorn}
            title="Blow Locomotive Horn (Web Audio API)"
            className={`relative flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold font-mono transition-all duration-300 ${
              hornPlaying
                ? 'bg-amber-500 text-slate-950 scale-105 shadow-[0_0_20px_rgba(245,158,11,0.8)]'
                : 'bg-amber-500/15 hover:bg-amber-500/25 text-amber-300 border border-amber-500/30 shadow-[0_0_12px_rgba(245,158,11,0.15)]'
            }`}
          >
            <Zap className={`w-3.5 h-3.5 ${hornPlaying ? 'animate-bounce' : ''}`} />
            <span className="hidden sm:inline">HORN</span>
          </button>

          {/* Audio Chime Mute/Unmute */}
          <button
            onClick={toggleSound}
            title={soundActive ? 'Mute Audio Announcements & Chimes' : 'Enable Audio'}
            className={`p-2 rounded-xl transition-all duration-300 border ${
              soundActive
                ? 'bg-cyan-500/15 text-cyan-300 border-cyan-500/40 hover:bg-cyan-500/25 shadow-[0_0_12px_rgba(6,182,212,0.2)]'
                : 'bg-slate-800 text-slate-500 border-slate-700 hover:text-slate-300'
            }`}
          >
            {soundActive ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
          </button>
        </div>
      </div>
    </header>
  );
};
